import{_ as s,o as i,c as t,a5 as o}from"./chunks/framework.BvXk9IVy.js";const r=JSON.parse('{"title":"把首页写成组件，而不是配置","description":"","frontmatter":{"title":"把首页写成组件，而不是配置"},"headers":[],"relativePath":"notes/custom-homepage.md","filePath":"notes/custom-homepage.md","lastUpdated":1791895356000}'),a={name:"notes/custom-homepage.md"};function d(c,e,n,l,p,h){return i(),t("div",null,[...e[0]||(e[0]=[o(`<h1 id="把首页写成组件-而不是配置" tabindex="-1">把首页写成组件，而不是配置</h1><blockquote><p>配置能给你的，是它能想到的版式；想不到的那部分，只能自己写。</p></blockquote><h2 id="layout-home-为什么不够" tabindex="-1"><code>layout: home</code> 为什么不够</h2><p>VitePress 自带的首页布局很好用：填几段文字，配几个 <code>features</code>，一分钟就能出一屏。但它本质上是一套已经拼好的积木——头像、标题、标语、按钮，位置和层数都定死了。</p><p>我想要的是一块能压住整屏的横幅：头像带一圈缓慢旋转的描金环，背景图在背后极慢地漂移，四角有一点点描金的窗棂。这些在配置里没有对应的字段，硬凑只会凑出四不像。</p><p>于是首页改成了 <code>layout: doc</code>——就是我手写 <code>index.md</code> 时写在最上面那一行。改成 doc 之后，整页交回给 Markdown，我在里面直接写 <code>&lt;HomeHero /&gt;</code>，版式全在组件的 <code>&lt;style scoped&gt;</code> 里。</p><p>代价也清楚：<strong>导航栏的高亮会失效</strong>。默认主题靠页面的 frontmatter 判断当前在哪个栏目，一个手写的首页没有归属，所以顶栏哪个都不亮。我接受了这件事——首页本来就谁的栏目也不是。真要修，就得改主题的 <code>Layout.vue</code>，为一次高亮去改主题，不划算。</p><h2 id="站内链接少了-withbase-就会-404" tabindex="-1">站内链接少了 <code>withBase()</code> 就会 404</h2><p>这是我在 <code>LinkCard.vue</code> 上踩过的一个坑，写下来给后来的人省一个下午。</p><p>这个站部署在 <code>yichen0808.github.io/Blog-pages/</code>，也就是说 <code>base</code> 是 <code>/Blog-pages/</code>。Markdown 里的链接由 VitePress 在构建期处理，会自动带上这个前缀。但<strong>组件里自己拼出来的 <code>href</code> 不会</strong>——它是运行时的字符串，构建器看不见。</p><p>所以 <code>LinkCard</code> 里必须显式调 <code>withBase()</code>：</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes rose-pine-dawn rose-pine-moon vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#286983;--shiki-dark:#3E8FB0;">import </span><span style="--shiki-light:#797593;--shiki-dark:#908CAA;">{</span><span style="--shiki-light:#575279;--shiki-light-font-style:italic;--shiki-dark:#E0DEF4;--shiki-dark-font-style:italic;"> withBase</span><span style="--shiki-light:#797593;--shiki-dark:#908CAA;"> }</span><span style="--shiki-light:#286983;--shiki-dark:#3E8FB0;"> from </span><span style="--shiki-light:#EA9D34;--shiki-dark:#F6C177;">&#39;vitepress&#39;</span></span></code></pre></div><p>少这一步，写 <code>/notes/lyric-scroll</code> 得到的路径就是站点的根，而不是 <code>/Blog-pages/</code> 下面，点进去是 404。</p><p>还有一层更细的：VitePress 默认 <code>cleanUrls: false</code>，产物是 <code>novels/xuezhong.html</code>。Markdown 里的链接会被自动补上 <code>.html</code>，但组件拼出来的不会，所以要照着 <code>site.value.cleanUrls</code> 自己补一次。</p><p>最后是 <code>target</code> 的取舍。站内链接<strong>不能</strong>加 <code>target</code>，因为 VitePress 的客户端路由靠一个挂在 <code>window</code> 上的点击拦截器工作，它要求同源、路径是 html、且 <code>&lt;a&gt;</code> 上没有 <code>target</code>。加了 <code>target</code> 就会被跳过，退化成整页刷新，白屏一下再回来。站外链接则相反，必须带上 <code>target=&quot;_blank&quot;</code>，让拦截器主动放行。</p><h2 id="vp-doc-的那点特异性" tabindex="-1"><code>.vp-doc</code> 的那点特异性</h2><p>组件写在 Markdown 里，就会落在 <code>.vp-doc</code> 这个容器内部，于是默认主题给它下面所有 <code>&lt;a&gt;</code> 加的链接色和下划线，也会落到卡片上。</p><p>处理办法是在组件自己的样式里直接压掉：</p><div class="language-css vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki shiki-themes rose-pine-dawn rose-pine-moon vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#797593;--shiki-light-font-style:italic;--shiki-dark:#908CAA;--shiki-dark-font-style:italic;">.</span><span style="--shiki-light:#907AA9;--shiki-light-font-style:italic;--shiki-dark:#C4A7E7;--shiki-dark-font-style:italic;">link-card</span><span style="--shiki-light:#797593;--shiki-dark:#908CAA;"> {</span></span>
<span class="line"><span style="--shiki-light:#56949F;--shiki-dark:#9CCFD8;">  color</span><span style="--shiki-light:#797593;--shiki-dark:#908CAA;">:</span><span style="--shiki-light:#B4637A;--shiki-light-font-style:italic;--shiki-dark:#EB6F92;--shiki-dark-font-style:italic;"> var</span><span style="--shiki-light:#797593;--shiki-dark:#908CAA;">(</span><span style="--shiki-light:#575279;--shiki-light-font-style:italic;--shiki-dark:#E0DEF4;--shiki-dark-font-style:italic;">--lc-ink</span><span style="--shiki-light:#797593;--shiki-dark:#908CAA;">);</span></span>
<span class="line"><span style="--shiki-light:#56949F;--shiki-dark:#9CCFD8;">  text-decoration</span><span style="--shiki-light:#797593;--shiki-dark:#908CAA;">:</span><span style="--shiki-light:#EA9D34;--shiki-dark:#F6C177;"> none</span><span style="--shiki-light:#797593;--shiki-dark:#908CAA;">;</span></span>
<span class="line"><span style="--shiki-light:#797593;--shiki-dark:#908CAA;">}</span></span></code></pre></div><p>这个选择器比默认主题的 <code>a</code> 更强，能赢。但同样是「谁赢」的问题，在别处就没这么轻松了：比如时间线那几条，<code>.vp-doc h3</code> 的特异性是 <code>(0,1,1)</code>，我写 <code>.tl-item h3</code> 只能打平，胜负取决于 CSS 的加载顺序。所以那些选择器一律带上 <code>.timeline</code> 前缀，变成 <code>(0,2,1)</code>——不赌顺序，比事后调试便宜。</p><h2 id="小结" tabindex="-1">小结</h2><p>首页写成组件，得到的是完全的控制权，付出的是几处默认行为要自己接回来：导航高亮、base 前缀、<code>.html</code> 后缀、锚点样式。这些都不难，难的是不知道它们存在。所以我把每一条都写进了组件的注释里——半年后的我，就是那个不知道的人。</p>`,22)])])}const g=s(a,[["render",d]]);export{r as __pageData,g as default};
